    expect(dark).toContain("color-scheme:dark");
    expect(dark).toContain("--moneo-accent:");
    expect(dark).toContain(".m-card{");
    expect(artifactDocument("<p>hi</p>", {})).toContain("color-scheme:light dark");
  });

